"""Word report: docxtpl fills templates/report.docx (generated by scripts/build_template.py)."""
from __future__ import annotations

import io
from importlib import resources

from docx.shared import Cm
from docxtpl import DocxTemplate, InlineImage, Listing

from qreport.notes import Notes
from qreport.render.bundle import render_chart_pngs
from qreport.render.content import TEMPLATE_VERSION, build_content

__all__ = ["TEMPLATE_VERSION", "render_docx"]

IMG_WIDTH = Cm(16)
TREND_WIDTH = Cm(12)


def _label(doc, text: str) -> None:
    """Visible data label above the cover title and in every page header."""
    title = next((p for p in doc.paragraphs if p.style.name == "Title"), None)
    para = title.insert_paragraph_before(text) if title is not None else doc.paragraphs[0].insert_paragraph_before(text)
    para.runs[0].bold = True
    for section in doc.sections:
        header = section.header
        header.is_linked_to_previous = False
        header.paragraphs[0].add_run(text).bold = True


def render_docx(result, notes: Notes, doc_no: str, pngs: dict[str, bytes] | None = None,
                data_label: str | None = None) -> bytes:
    """data_label (e.g. "가상 데이터 — 체험용 샘플") marks the cover and every page header; None = no mark."""
    pngs = render_chart_pngs(result) if pngs is None else pngs
    tpl = DocxTemplate(str(resources.files("qreport") / "templates" / "report.docx"))

    def img(key: str) -> InlineImage:
        return InlineImage(tpl, io.BytesIO(pngs[key]), width=TREND_WIDTH if key == "trend" else IMG_WIDTH)

    ctx = build_content(result, notes, doc_no)
    ctx["issues"] = Listing(ctx["issues"])
    for key in pngs:
        if not key.startswith("pchart_"):
            ctx[f"img_{key}"] = img(key)
    ctx["model_pcharts"] = [{"img": img(f"pchart_{m}")} for m in ctx["models"]]
    tpl.render(ctx, autoescape=True)
    if data_label:
        _label(tpl.docx, data_label)
    buf = io.BytesIO()
    tpl.save(buf)
    return buf.getvalue()
